import Blockly from 'blockly/core';
import 'blockly/blocks';
import { pythonGenerator } from 'blockly/python';

Blockly.Blocks['struct_create'] = {
  init: function() {
    this.appendDummyInput()
        .appendField('create struct');
    this.setColour("#c70303");
    this.setTooltip('Create a struct with fields');
    this.setDeletable(true);
    this.setMovable(true);
    
    // Initialize with one field
    this.fieldCount_ = 1;
    this.updateShape_();

    // Set up the mutator
    this.mutator = new Blockly.Mutator(['struct_field']);
    this.mutator.icon = new Blockly.icons.MutatorIcon(this.mutator, this);
  },

  saveExtraState: function() {
    return {
      'fieldCount': this.fieldCount_
    };
  },

  loadExtraState: function(state) {
    this.fieldCount_ = state['fieldCount'];
    this.updateShape_();
  },

  decompose: function(workspace) {
    const containerBlock = workspace.newBlock('struct_container');
    containerBlock.initSvg();
    let connection = containerBlock.getInput('STACK').connection;
    
    for (let i = 0; i < this.fieldCount_; i++) {
      const itemBlock = workspace.newBlock('struct_field');
      itemBlock.initSvg();
      connection.connect(itemBlock.previousConnection);
      connection = itemBlock.nextConnection;
    }
    
    return containerBlock;
  },

  compose: function(containerBlock) {
    let itemBlock = containerBlock.getInputTargetBlock('STACK');
    const connections = [];
    const names = [];
    const types = [];
    
    while (itemBlock && !itemBlock.isInsertionMarker()) {
      connections.push(itemBlock.valueConnection_);
      names.push(itemBlock.getFieldValue('FIELD_NAME'));
      types.push(itemBlock.getFieldValue('FIELD_TYPE'));
      itemBlock = itemBlock.nextConnection && itemBlock.nextConnection.targetBlock();
    }
    
    this.fieldCount_ = connections.length;
    this.updateShape_();
    
    // Reconnect blocks and restore field properties
    for (let i = 0; i < this.fieldCount_; i++) {
      if (connections[i]) {
        this.getInput('FIELD' + i).connection.connect(connections[i]);
      }
      if (names[i]) {
        this.setFieldValue(names[i], 'FIELD_NAME' + i);
      }
      if (types[i]) {
        this.setFieldValue(types[i], 'FIELD_TYPE' + i);
      }
    }
  },

  saveConnections: function(containerBlock) {
    let itemBlock = containerBlock.getInputTargetBlock('STACK');
    let i = 0;
    while (itemBlock) {
      const input = this.getInput('FIELD' + i);
      itemBlock.valueConnection_ = input && input.connection.targetConnection;
      itemBlock = itemBlock.nextConnection && itemBlock.nextConnection.targetBlock();
      i++;
    }
  },

  updateShape_: function() {
    // Remove any existing FIELD inputs
    for (let i = 0; i < this.fieldCount_; i++) {
      if (this.getInput('FIELD' + i)) {
        this.removeInput('FIELD' + i);
      }
    }

    // Add new FIELD inputs
    for (let i = 0; i < this.fieldCount_; i++) {
      const input = this.appendValueInput('FIELD' + i)
        .setCheck(null)
        .appendField(i === 0 ? 'with field' : 'and field')
        .appendField(new Blockly.FieldTextInput(''), 'FIELD_NAME' + i)
        .appendField(':', 'SEPARATOR' + i)
        .appendField(new Blockly.FieldDropdown([
          ['int', 'int'],
          ['float', 'float'],
          ['str', 'str'],
          ['bool', 'bool'],
          ['list', 'list'],
          ['dict', 'dict'],
        ]), 'FIELD_TYPE' + i);
      
      // Move the input to the correct position
      if (i > 0) {
        this.moveInputBefore('FIELD' + i, 'FIELD' + (i - 1));
      }
    }
  }
};

Blockly.Blocks['struct_container'] = {
  init: function() {
    this.setColour("#c70303");
    this.appendDummyInput()
        .appendField('struct');
    this.appendStatementInput('STACK');
    this.setTooltip('Add, remove, or reorder fields to reconfigure this struct');
    this.contextMenu = false;
  }
};

Blockly.Blocks['struct_field'] = {
  init: function() {
    this.setColour("#c70303");
    this.appendDummyInput()
        .appendField('field')
        .appendField(new Blockly.FieldTextInput(''), 'FIELD_NAME')
        .appendField(':', 'SEPARATOR')
        .appendField(new Blockly.FieldDropdown([
          ['int', 'int'],
          ['float', 'float'],
          ['str', 'str'],
          ['bool', 'bool'],
          ['list', 'list'],
          ['dict', 'dict'],
        ]), 'FIELD_TYPE');
    this.setPreviousStatement(true);
    this.setNextStatement(true);
    this.setTooltip('Add a field to the struct');
    this.contextMenu = false;
  }
};

pythonGenerator.forBlock['struct_create'] = function(block) {
  var structName = block.getFieldValue('STRUCT_NAME') || 'MyStruct';
  var fields = [];
  for (var i = 0; i < block.fieldCount_; i++) {
    var fieldName = block.getFieldValue('FIELD_NAME' + i) || 'field' + (i + 1);
    var fieldValue = pythonGenerator.valueToCode(block, 'FIELD' + i,
        pythonGenerator.ORDER_NONE) || 'None';
    fields.push(fieldName + ' = ' + fieldValue);
  }
  var code = 'class ' + structName + ':\n' +
             '    def __init__(self):\n' +
             '        ' + fields.join('\n        ');
  return [code, pythonGenerator.ORDER_NONE];
};

Blockly.Blocks['struct_get'] = {
  init: function() {
    this.appendValueInput('STRUCT')
        .setCheck(null)
        .appendField('get field');
    this.appendValueInput('FIELD')
        .setCheck('String')
        .appendField('from struct');
    this.setOutput(true, null);
    this.setColour(160);
    this.setTooltip('Get a field value from a struct');
  }
};

pythonGenerator.forBlock['struct_get'] = function(block) {
  const struct = pythonGenerator.valueToCode(block, 'STRUCT', pythonGenerator.ORDER_MEMBER) || 'struct';
  const field = pythonGenerator.valueToCode(block, 'FIELD', pythonGenerator.ORDER_ATOMIC) || "'field'";
  return [`${struct}.${field}`, pythonGenerator.ORDER_MEMBER];
};

Blockly.Blocks['struct_set'] = {
  init: function() {
    this.appendValueInput('STRUCT')
        .setCheck(null)
        .appendField('set field');
    this.appendValueInput('FIELD')
        .setCheck('String')
        .appendField('in struct');
    this.appendValueInput('VALUE')
        .setCheck(null)
        .appendField('to');
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(160);
    this.setTooltip('Set a field value in a struct');
  }
};

pythonGenerator.forBlock['struct_set'] = function(block) {
  const struct = pythonGenerator.valueToCode(block, 'STRUCT', pythonGenerator.ORDER_MEMBER) || 'struct';
  const field = pythonGenerator.valueToCode(block, 'FIELD', pythonGenerator.ORDER_ATOMIC) || "'field'";
  const value = pythonGenerator.valueToCode(block, 'VALUE', pythonGenerator.ORDER_ATOMIC) || 'None';
  return `${struct}.${field} = ${value}\n`;
};
